<script setup lang="ts">
import {CLUB_PHOTOS,CLUB_PHONE} from '#shared/club-content'
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value))
const api=inject<any>('adminFetch'),section=ref('home'),error=ref(''),message=ref(''),pending=ref(false)
const pages=ref<Record<string,any>>({})
const sections=[{id:'home',label:'Главная'},{id:'club',label:'Клуб'},{id:'information',label:'Информация'},{id:'contacts',label:'Контакты'}]
const form=reactive({title:'',text:'',phone:CLUB_PHONE,address:'',images:[] as {url:string;alt:string}[]})
function select(){Object.assign(form,{title:'',text:'',phone:CLUB_PHONE,address:'',images:section.value==='club'?clone(CLUB_PHOTOS):[]},clone(pages.value[section.value]||{}));message.value=''}
async function load(){try{pages.value=await api('/api/admin/site-content');select()}catch(e:any){error.value=e?.data?.message||'Не удалось загрузить страницы'}}
async function save(){pending.value=true;error.value='';message.value='';try{await api('/api/admin/site-content',{method:'PUT',body:{section:section.value,content:{...form,phone:CLUB_PHONE}}});pages.value[section.value]=clone(toRaw(form));message.value='Страница сохранена'}catch(e:any){error.value=e?.data?.message||'Не удалось сохранить страницу'}finally{pending.value=false}}
onMounted(load)
</script>
<template><section class="max-w-3xl"><h2 class="mb-5 text-3xl">Контент страниц</h2><p class="mb-4 text-sm text-ash">Меняйте заголовки, основной текст и фотографии. Политика и согласия редактируются отдельно в коде.</p><label class="block">Страница<select v-model="section" class="input mt-1" @change="select"><option v-for="s in sections" :key="s.id" :value="s.id">{{s.label}}</option></select></label><form class="card mt-5 space-y-4" @submit.prevent="save"><label class="block">Заголовок<input v-model="form.title" class="input mt-1" maxlength="250"/></label><label class="block">Основной текст<textarea v-model="form.text" class="input mt-1" rows="8" maxlength="20000"/></label><template v-if="section==='contacts'"><p>Телефон: +7 (904) 090-17-64</p><label class="block">Точный адрес<input v-model="form.address" class="input mt-1" maxlength="500"/><span class="text-xs text-ash">Укажите реальный адрес клуба — он будет использован в ссылке на карту.</span></label></template><p class="text-sm text-ash">На главной первое изображение используется как фон первого экрана; в контактах первое фото — изображение клуба. В разделе «Клуб» фотографии образуют галерею.</p><div v-for="(image,i) in form.images" :key="i" class="space-y-3 border-t border-white/10 pt-4"><AdminImagePicker v-model="image.url"/><label class="block">Описание фотографии<input v-model="image.alt" class="input mt-1" maxlength="300"/></label><div class="flex gap-2"><button v-if="i>0" type="button" class="btn-ghost" @click="[form.images[i-1],form.images[i]]=[form.images[i],form.images[i-1]]">Выше</button><button type="button" class="btn-ghost" @click="form.images.splice(i,1)">Убрать фото</button></div></div><button type="button" class="btn-ghost" @click="form.images.push({url:'',alt:''})">Добавить фотографию</button><p v-if="error" role="alert" class="text-red-300">{{error}}</p><p v-if="message" role="status" class="text-green-300">{{message}}</p><div><button class="btn-primary" :disabled="pending">{{pending?'Сохраняем…':'Сохранить страницу'}}</button></div></form></section></template>
